If $f(a)=b$ then $f^{-1}(b)=a$, so the point $(a,b)$ on $f$ becomes the point $(b,a)$ on $f^{-1}$.
[tikz]\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{arrows.meta}
\begin{axis}[axis lines=middle, xlabel={$x$}, ylabel={$y$},
             xmin=-3.6, xmax=3.6, ymin=-3.4, ymax=3.4,
             xtick=\empty, ytick=\empty, samples=100, clip=false,
             axis line style={-{Stealth}}]
\addplot[thick, <->, domain=-2.1:2.1] {x*x*x/3};
\addplot[thick, <->, domain=-2.1:2.1, variable=\t] ({t*t*t/3}, {t});
\addplot[dashed, domain=-3:3] {x};
\addplot[only marks, mark=*] coordinates {(1.5,1.125) (1.125,1.5)};
\addplot[dashed] coordinates {(1.5,1.125) (1.125,1.5)};
\node[below right] at (axis cs:1.5,1.125) {$(a,b)$};
\node[above left] at (axis cs:1.125,1.5) {$(b,a)$};
\node[font=\small] at (axis cs:1.15,3.12) {$y=f(x)$};
\node[font=\small] at (axis cs:2.9,1.45) {$y=f^{-1}(x)$};
\node[fill=white, inner sep=1pt] at (axis cs:-2.75,-2.75) {$y=x$};
\end{axis}
\end{tikzpicture}[/tikz]
